// Explicit identifiers in retained PubMed Author/GrantList/DataBankList nodes.
// Agency text scopes source grant assertions; it is not a global funder crosswalk.
// RawSHA256 is unavailable: retained metadata has batch lineage, not raw provider bytes.
(History as table, Files as table) as list =>
let
    Rows=Table.Buffer(History),
    BatchIDs=List.Buffer(List.Distinct(Rows[LastBatchID])),
    Times=Record.FromList(List.Transform(BatchIDs,(B)=>let Matches=Table.SelectRows(Files,each [Name]="commit-"&B&".json") in if Table.RowCount(Matches)=1 then Json.Document(Matches{0}[Content])[ObservedAtUTC] else error "PubMed source generation missing or duplicated"),BatchIDs),
    Children=(N as any,Name as text) as list => let V=if Value.Is(N,type list) then N else if Value.Is(N,type record) then Record.FieldOrDefault(N,"Value",{}) else {} in if Value.Is(V,type list) then List.Select(V,each Value.Is(_,type record) and Record.FieldOrDefault(_,"Name","")=Name) else {},
    Child=(N as any,Name as text) as record => List.First(Children(N,Name),[]),
    NodeText=(N as any) as text => let V=if Value.Is(N,type record) then Record.FieldOrDefault(N,"Value","") else N in if V=null then "" else if Value.Is(V,type list) then Text.Combine(List.Transform(V,each @NodeText(_)),"") else if Value.Is(V,type text) then V else Text.From(V),
    Attribute=(N as record,Name as text) as text => NodeText(List.First(List.Select(Record.FieldOrDefault(N,"Attributes",{}),each Record.FieldOrDefault(_,"Name","")=Name),[])),
    NormalORCID=(S as text) as text => Text.Replace(Text.Replace(Text.Trim(S),"https://orcid.org/",""),"http://orcid.org/",""),
    ORCIDStatus=(S as text) as text => let T=NormalORCID(S),Digits=Text.Replace(T,"-",""),Shape=Text.Length(T)=19 and Text.Middle(T,4,1)="-" and Text.Middle(T,9,1)="-" and Text.Middle(T,14,1)="-" and Text.Length(Digits)=16 and Text.Select(Text.Start(Digits,15),{"0".."9"})=Text.Start(Digits,15),Total=if Shape then List.Accumulate(Text.ToList(Text.Start(Digits,15)),0,(A,C)=>(A+Number.FromText(C))*2) else 0,Check=Number.Mod(12-Number.Mod(Total,11),11),Expected=if Check=10 then "X" else Text.From(Check) in if S="" then "Absent" else if Shape and Text.End(T,1)=Expected then "Valid syntax; unauthenticated" else "Invalid",
    Hex=(S as text) as text => Text.Upper(Binary.ToText(Text.ToBinary(S,TextEncoding.Utf8),BinaryEncoding.Hex)),
    PairRows=(IDs as list) as list => List.Combine(List.Transform(List.Positions(IDs),(I)=>List.Transform(List.Skip(IDs,I+1),(B)=>[A=IDs{I},B=B]))),
    Parsed=List.Buffer(List.Transform(Table.ToRecords(Rows),(R)=>let Tree=Json.Document(R[MetadataJSON]),Citation=Child(Tree,"MedlineCitation"),Valid=NodeText(Child(Citation,"PMID"))=R[SourceID] in if Valid then [Row=R,Article=Child(Citation,"Article")] else error "PubMed relationship PMID identity drift")),
    Evidence=List.Buffer(List.Combine(List.Transform(Parsed,(R)=>let
        PMID=R[Row][SourceID],Source="pubmed:"&PMID,Article=R[Article],
        Add=(Kind as text,F as text,T as text,FL as text,TL as text,O as text,State as text,ReferenceType as text) as record => [EvidenceKey=Text.Combine({Source,Kind,F,T},"|") & (if Kind="publication_affiliation" then "|"&Hex(TL) else ""),RelationshipKind=Kind,SourceWorkID=Source,PublicationDOI="",PublicationPMID=PMID,ReferenceType=ReferenceType,FromKey=F,ToKey=T,FromLabel=FL,ToLabel=TL,ORCID=O,ORCIDStatus=ORCIDStatus(O),ROR="",IdentityStatus=State,SourceURL="https://pubmed.ncbi.nlm.nih.gov/"&PMID&"/",ObservedUTC=Record.Field(Times,R[Row][LastBatchID]),RawSHA256="",SourceVersion=R[Row][LastBatchID],ReviewState="Not reviewed",AuthenticationState="Not authenticated"],
        As=Children(Child(Article,"AuthorList"),"Author"),
        Authors=List.Buffer(List.Transform(List.Positions(As),(I)=>let A=As{I},Collective=NodeText(Child(A,"CollectiveName")),First=NodeText(Child(A,"ForeName")),Name=if Collective<>"" then Collective else Text.Combine(List.Select({if First="" then NodeText(Child(A,"Initials")) else First,NodeText(Child(A,"LastName")),NodeText(Child(A,"Suffix"))},each _<>"")," "),IDs=List.Sort(List.Distinct(List.Transform(List.Select(Children(A,"Identifier"),each Attribute(_,"Source")="ORCID"),each NormalORCID(NodeText(_))))),O=if List.Count(IDs)=1 then IDs{0} else "",Good=List.Count(IDs)=1 and Text.StartsWith(ORCIDStatus(O),"Valid"),Key=if Good then "orcid:"&O else Source&"/unresolved-author/"&Text.From(I+1),State=if Good then "Source-supported" else if List.Count(IDs)>1 then "Conflicting identifiers" else "Unresolved identity" in [Key=Key,Name=Name,ORCID=O,State=State,Affiliations=Children(A,"AffiliationInfo")])),
        Authorships=List.Buffer(List.Transform(Authors,each Add("authorship","pmid:"&PMID,[Key],"",[Name],[ORCID],[State],""))),
        Affiliations=List.Buffer(List.Combine(List.Transform(Authors,(A)=>List.Combine(List.Transform(A[Affiliations],(AF)=>let Label=NodeText(Child(AF,"Affiliation")),IDs=List.Select(Children(AF,"Identifier"),each Attribute(_,"Source")="RINGGOLD" and NodeText(_)<>"" and Text.Select(NodeText(_),{"0".."9"})=NodeText(_)) in List.Transform(IDs,(ID)=>Add("publication_affiliation",A[Key],"ringgold:"&NodeText(ID),A[Name],Label,A[ORCID],A[State],""))))))),
        Good=List.Buffer(List.Select(Authors,each [State]="Source-supported")),AIDs=List.Buffer(List.Sort(List.Distinct(List.Transform(Good,each [Key])))),NameFor=(ID as text) as text => List.First(List.Select(Good,each [Key]=ID))[Name],
        Coauthors=List.Transform(PairRows(AIDs),each Add("coauthorship",[A],[B],NameFor([A]),NameFor([B]),"","Source-supported","")),
        IIDs=List.Buffer(List.Sort(List.Distinct(List.Transform(Affiliations,each [ToKey])))),IName=(ID as text) as text => List.First(List.Select(Affiliations,each [ToKey]=ID))[ToLabel],
        Institutions=List.Transform(PairRows(IIDs),each Add("institution_cooccurrence",[A],[B],IName([A]),IName([B]),"","Source-supported","")),
        Awards=List.RemoveNulls(List.Transform(Children(Child(Article,"GrantList"),"Grant"),(G)=>let Number=NodeText(Child(G,"GrantID")),Agency=NodeText(Child(G,"Agency")),Country=NodeText(Child(G,"Country")),Key="pubmed:grant:"&Text.Combine(List.Transform({Agency,Country,Number},Hex),"|") in if Number="" then null else Add("publication_grant_reference","pmid:"&PMID,Key,"",Agency&" | "&Number,"",if Agency="" then "Unresolved award namespace" else "Source-supported","PubMed GrantList; source-scoped agency label"))),
        TrialRefs=List.Combine(List.Transform(Children(Child(Article,"DataBankList"),"DataBank"),(DB)=>let Name=Text.Lower(NodeText(Child(DB,"DataBankName"))),Scheme=if Name="clinicaltrials.gov" then [Name="clinicaltrials.gov",Prefix="NCT",Digits=8] else if Name="anzctr" then [Name="anzctr",Prefix="ACTRN",Digits=14] else if Name="isrctn" then [Name="isrctn",Prefix="ISRCTN",Digits=8] else null,Numbers=Children(Child(DB,"AccessionNumberList"),"AccessionNumber") in if Scheme=null then {} else List.RemoveNulls(List.Transform(Numbers,(N)=>let Value=Text.Upper(Text.Trim(NodeText(N))),Suffix=if Text.StartsWith(Value,Scheme[Prefix]) then Text.Range(Value,Text.Length(Scheme[Prefix])) else "",Valid=Text.Length(Suffix)=Scheme[Digits] and Text.Select(Suffix,{"0".."9"})=Suffix in if Valid then Add("publication_study_reference","pmid:"&PMID,Scheme[Name]&":"&Value,"",Value,"","Source-supported","PubMed DataBankList") else null))))
        in {Add("publication","pmid:"&PMID,Source,"","","","Source-supported","")} & Authorships & Affiliations & Coauthors & Institutions & Awards & TrialRefs)))
in Evidence
